      min-block-size: 0;
    }
  }

  .card-columns__left {
    justify-content: end;
    margin-inline-start: auto;
    padding-inline-start: var(--column-gap);

    @media (max-width: 639px) {
      padding-inline-start: calc(var(--column-gap) * 2);
    }
  }

  .card-columns__right {
    justify-content: start;
    padding-inline-end: var(--column-gap);
    margin-inline-end: auto;
  }

